# Homebrew formula for the paxel/tap tap — generated by the release workflow,
# which fills in the tagged version and the sha256 of each release tarball and
# pushes the result to the homebrew-tap repository as Formula/dedup.rb.
# Binary formula: it installs the prebuilt `dedup`.
class Dedup < Formula
  desc "Forensic data-inheritance triage: dedupe, diff and browse file piles"
  homepage "https://github.com/paxel/dedup-rs"
  version "0.2.1"
  license "MIT"

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/paxel/dedup-rs/releases/download/v0.2.1/dedup-0.2.1-macos-arm64.tar.gz"
      sha256 "d4da2813491e37a4e5ff8a106342a7140cb279c455acaec4f68ac839f16064b4"
    else
      url "https://github.com/paxel/dedup-rs/releases/download/v0.2.1/dedup-0.2.1-macos-x86_64.tar.gz"
      sha256 "f3079d28b021a5a8b5fc882af73c57d1b7eeb27327d2555f0f3928acac7de9d8"
    end
  end

  on_linux do
    url "https://github.com/paxel/dedup-rs/releases/download/v0.2.1/dedup-0.2.1-linux-x86_64.tar.gz"
    sha256 "4d12c5cbedbb30632ef2999dae78ee1fc132b3ac826d0092025f7430f1a4dd10"
  end

  def install
    bin.install "dedup"
  end

  def caveats
    <<~EOS
      Optional tools unlock extra features (the app works without them):
        ffmpeg       — video previews, filmstrips, soundtrack playback
        poppler      — PDF page rendering (Render tab)
        libreoffice  — office/legacy document page rendering
    EOS
  end

  test do
    system "#{bin}/dedup", "--help"
  end
end
